type IconName = 'chart' | 'grid' | 'arrow' | 'chevron' | 'calendar' | 'download' | 'sun' | 'moon' | 'monitor' | 'users' | 'activity' | 'target' | 'help' | 'close' | 'check' | 'globe' | 'link';
