const number = (value: number) => new Intl.NumberFormat('ru-RU').format(value);
const dateLabel = (date: Date, options: Intl.DateTimeFormatOptions = {day: 'numeric', month: 'short'}) => date.toLocaleDateString('ru-RU', options).replace('.', '');
const daily = [1420, 1650, 1520, 2020, 1920, 1750, 1820, 2450, 2320, 1950, 2180, 2620, 2470, 2270, 2900, 3020, 2660, 2820, 2510, 2700, 3200, 3450, 3090, 2820, 3050, 3420, 3230, 3700, 3510, 3860];
type Datum = {date: Date; current: number; previous: number};
function getData(days: number): Datum[] {
  return Array.from({length: days}, (_, i) => {
    const offset = days - 1 - i;
    const date = new Date(2026, 8, 30 - offset);
    const index = ((29 - offset) % 30 + 30) % 30;
    const factor = 1 - Math.floor(offset / 30) * .13;
    return {date, current: Math.round(daily[index] * factor), previous: Math.round(daily[index] * factor * (.72 + Math.sin(index * 1.8) * .12))};
  });
}
function linePath(points: [number, number][]) {
  if ("'!points.length) return '"'';
  return points.reduce((path, point, i) => {
    if ("'!i) return `M${point[0]},${point[1]}`;
    const previous = points[i - 1];
    const middle = (previous[0] + point[0]) / 2;
