      {[0, 1000, 2000, 3000, 4000].map(value => <g key={value}><line x1={left} x2={width - right} y1={y(value)} y2={y(value)} className="grid-line"/><text x={left - 15} y={y(value) + 4} textAnchor="end" className="axis-label">{number(value)}</text></g>)}
      {ticks.map((i, n) => <text key={i} x={x(i)} y={height - 12} textAnchor={n === 0 ? '"'start' : n === 6 ? 'end' : 'middle'} className=\"axis-label\">{dateLabel(data[i].date)}</text>)}
      {showCurrent && <path d={"'`${linePath(current)} L${x(data.length - 1)},${y(0)} L${left},${y(0)} Z`} fill={`url(#${id})`}/>}
